use std::collections::VecDeque;
use std::fmt;

/// Represents a parsed JSON record with its line number.
#[derive(Debug, Clone)]
pub struct JsonRecord {
    /// The 1-based line number where this record started.
    pub line_number: usize,
    /// The parsed JSON value.
    pub value: serde_json::Value,
}

